import { scienceTerms, primerTerms } from './terminology-data.js';
import { escapeHTML } from './components.js';
const byId=new Map(scienceTerms.map(t=>[t.id,t]));
const aliases=scienceTerms.flatMap(t=>[t.label,...t.aliases].map(label=>({label,id:t.id}))).filter(t=>t.label.length>1).sort((a,b)=>b.label.length-a.label.length);
const lookup=new Map(aliases.map(t=>[t.label,t.id]));
const pattern=new RegExp(aliases.map(t=>t.label.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'g');
export function termButton(id,label){const t=byId.get(id);return '<button type="button" class="science-term" data-science-term="'+id+'" aria-haspopup="dialog" aria-label="查看'+escapeHTML(t.label)+'的定義">'+escapeHTML(label||t.label)+'</button>';}
export function TermPrimer(card){const ids=primerTerms[card]||[];return '<section class="term-primer" data-glossary-skip aria-label="本站名詞定義"><div class="term-primer-heading"><div><span class="eyebrow">先認識用語，再動手找規律</span><h3>這幾個名詞是什麼意思？</h3></div><button class="secondary" data-open-glossary="'+card+'">查本站所有名詞</button></div><dl class="term-primer-grid">'+ids.map(id=>{const t=byId.get(id);return '<div><dt>'+termButton(id)+'</dt><dd>'+escapeHTML(t.definition)+'</dd>'+(t.unit?'<dd class="term-unit">'+escapeHTML(t.unit)+'</dd>':'')+'<dd class="term-example">例：'+escapeHTML(t.example)+'</dd></div>';}).join('')+'</dl><p class="term-help">課文中有虛線底線的名詞可以點開，看定義、例子與容易混淆的地方。</p></section>';}
export function matchScienceTerms(text){return [...String(text).matchAll(pattern)].map(m=>({term:lookup.get(m[0]),text:m[0],index:m.index}));}
export function mountTerminology(){
 const dialog=document.createElement('dialog');dialog.className='science-dictionary';dialog.setAttribute('aria-labelledby','dictionary-title');dialog.innerHTML='<div class="dictionary-head"><div><span class="eyebrow">隨手查，不用離開實驗</span><h2 id="dictionary-title">科學名詞小字典</h2></div><button type="button" class="dictionary-close" aria-label="關閉名詞字典">×</button></div><div class="dictionary-toolbar"><label for="dictionary-search">找名詞</label><input id="dictionary-search" type="search" placeholder="例如：原子量、分子量、莫耳"><select class="dictionary-filter" aria-label="依卡片篩選名詞"><option value="0">整章名詞</option>'+[1,2,3,4,5].map(n=>'<option value="'+n+'">第 '+n+' 站</option>').join('')+'</select></div><div class="dictionary-main"><nav class="dictionary-list" aria-label="名詞搜尋結果"></nav><article class="dictionary-detail" tabindex="-1"></article></div><p class="dictionary-source">定義參考 <a href="https://www.nist.gov/pml/special-publication-811/nist-guide-si-chapter-8" target="_blank" rel="noopener">NIST 相對質量</a>、<a href="https://www.bipm.org/en/si-base-units/mole" target="_blank" rel="noopener">BIPM 莫耳定義</a>；計算使用本章標明的近似值。</p>';
 document.body.append(dialog);const search=dialog.querySelector('input'),filter=dialog.querySelector('select'),list=dialog.querySelector('.dictionary-list'),detail=dialog.querySelector('.dictionary-detail');let selected='atomicweight',returnFocus=null;
 function select(id,focus=false){const t=byId.get(id);if(!t)return;selected=id;detail.innerHTML='<span class="eyebrow">名詞定義</span><h3>'+escapeHTML(t.label)+'</h3>'+(t.aliases.length?'<p class="term-alias">也會看到：'+t.aliases.map(escapeHTML).join('、')+'</p>':'')+'<p class="dictionary-definition">'+escapeHTML(t.definition)+'</p>'+(t.unit?'<p class="dictionary-unit"><b>單位與符號</b>'+escapeHTML(t.unit)+'</p>':'')+'<div class="dictionary-example"><b>用例子理解</b><p>'+escapeHTML(t.example)+'</p></div>'+(t.note?'<div class="dictionary-caution"><b>別混淆</b><p>'+escapeHTML(t.note)+'</p></div>':'')+((t.related||[]).length?'<div class="dictionary-related"><span>一起認識</span>'+t.related.map(id=>termButton(id)).join('')+'</div>':'');list.querySelectorAll('[data-dictionary-term]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.dictionaryTerm===id)));detail.scrollTop=0;if(dialog.open)list.querySelector('[aria-pressed="true"]')?.scrollIntoView({block:'nearest',behavior:'instant'});if(focus)detail.focus({preventScroll:true});}
 function renderList(){const q=search.value.trim().toLowerCase(),n=Number(filter.value),items=scienceTerms.filter(t=>(!n||t.chapters.includes(n))&&(!q||[t.label,...t.aliases,t.definition,t.example].join(' ').toLowerCase().includes(q)));list.innerHTML='<p class="dictionary-count" role="status">找到 '+items.length+' 個名詞</p>'+items.map(t=>'<button type="button" data-dictionary-term="'+t.id+'" aria-pressed="'+(t.id===selected)+'">'+escapeHTML(t.label)+'</button>').join('');if(!items.length){detail.innerHTML='<h3>沒有找到這個名詞</h3><p>試試較短的關鍵字，或把篩選改成「整章名詞」。</p>';return;}if(!items.some(t=>t.id===selected))selected=items[0].id;select(selected);}
 function open(trigger,id,chapter=0){returnFocus=trigger;search.value='';filter.value=String(chapter);selected=id||primerTerms[chapter]?.[0]||'atomicweight';renderList();if(id)select(id);if(!dialog.open)dialog.showModal();list.querySelector('[aria-pressed="true"]')?.scrollIntoView({block:'nearest',behavior:'instant'});detail.focus({preventScroll:true});}
 dialog.querySelector('.dictionary-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}const b=e.target.closest('[data-dictionary-term]');if(b)select(b.dataset.dictionaryTerm,true);});
 search.oninput=renderList;filter.onchange=renderList;
 document.addEventListener('click',e=>{const term=e.target.closest('[data-science-term]'),all=e.target.closest('[data-open-glossary]');if(term){if(dialog.contains(term)){select(term.dataset.scienceTerm,true);return;}open(term,term.dataset.scienceTerm);}else if(all)open(all,null,Number(all.dataset.openGlossary)||0);});
 const skip='button,a,svg,script,style,input,select,textarea,label,summary,dialog,[data-glossary-skip],.molecule-art,[role="status"],[aria-live]';
 function annotate(scope){if(!scope?.isConnected)return;const element=scope.nodeType===3?scope.parentElement:scope;if(!element||element.closest(skip))return;const card=element.closest('.learning-card');if(!card)return;const seen=new Set([...card.querySelectorAll('.science-term[data-inline-term]')].map(b=>b.dataset.scienceTerm));const nodes=[];if(scope.nodeType===3)nodes.push(scope);else{const walker=document.createTreeWalker(scope,NodeFilter.SHOW_TEXT);while(walker.nextNode())nodes.push(walker.currentNode);}for(const node of nodes){if(!node.parentElement||node.parentElement.closest(skip))continue;const matches=matchScienceTerms(node.data).filter(m=>!seen.has(m.term));if(!matches.length)continue;const fragment=document.createDocumentFragment();let end=0;for(const m of matches){if(seen.has(m.term))continue;fragment.append(document.createTextNode(node.data.slice(end,m.index)));const b=document.createElement('button');b.type='button';b.className='science-term';b.dataset.scienceTerm=m.term;b.dataset.inlineTerm='';b.setAttribute('aria-haspopup','dialog');b.setAttribute('aria-label','查看'+byId.get(m.term).label+'的定義');b.textContent=m.text;fragment.append(b);seen.add(m.term);end=m.index+m.text.length;}fragment.append(document.createTextNode(node.data.slice(end)));node.replaceWith(fragment);}}
 const pending=new Set();let scheduled=false;const observer=new MutationObserver(records=>{for(const r of records){if(r.target.nodeType===1&&r.target.closest(skip))continue;if(r.type==='characterData')pending.add(r.target);else for(const n of r.addedNodes)if(n.nodeType===1||n.nodeType===3)pending.add(n);}if(pending.size&&!scheduled){scheduled=true;queueMicrotask(()=>{scheduled=false;observer.disconnect();for(const n of pending)annotate(n);pending.clear();observer.observe(document.querySelector('#lesson'),{childList:true,subtree:true,characterData:true});});}});
 document.querySelectorAll('.learning-card').forEach(annotate);observer.observe(document.querySelector('#lesson'),{childList:true,subtree:true,characterData:true});
 return{disconnect(){observer.disconnect();dialog.remove();}};
}
